:root {
  --bg: #111111;
  --bg-soft: #181818;
  --panel: #1f1f1f;
  --text: #f5f5f5;
  --muted: #b8b8b8;
  --accent: #e63946;
  --accent-dark: #b2202d;
  --line: #2b2b2b;
  --success: #4caf50;
  --danger: #ff5a5f;
  --radius: 12px;
  --max: 1200px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  line-height: 1.5;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }

.container {
  width: min(var(--max), 92%);
  margin: 0 auto;
}

.top-promo {
  background: var(--accent);
  color: #fff;
  text-align: center;
  padding: 0.55rem 1rem;
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: 0.03em;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(17,17,17,0.95);
  backdrop-filter: blur(6px);
  border-bottom: 1px solid var(--line);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 74px;
}
.brand {
  font-family: 'Oswald', 'Bebas Neue', sans-serif;
  text-transform: uppercase;
  font-size: 1.5rem;
  letter-spacing: 0.08em;
  font-weight: 700;
}
.brand .dot { color: var(--accent); }
.nav-links {
  display: flex;
  gap: 1.2rem;
  align-items: center;
  flex-wrap: wrap;
}
.nav-links a {
  color: var(--muted);
  text-transform: uppercase;
  font-family: 'Oswald', sans-serif;
  letter-spacing: 0.06em;
  font-size: 0.95rem;
}
.nav-links a:hover,
.nav-links a.active { color: #fff; }

.btn {
  border: none;
  border-radius: 999px;
  padding: 0.82rem 1.35rem;
  font-weight: 700;
  cursor: pointer;
  transition: 0.25s ease;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover { background: var(--accent-dark); transform: translateY(-1px); }
.btn-outline {
  border: 1px solid #fff;
  background: transparent;
  color: #fff;
}
.btn-outline:hover { background: #fff; color: #111; }

.hero {
  min-height: 72vh;
  display: grid;
  place-items: center;
  text-align: center;
  position: relative;
  overflow: hidden;
  border-bottom: 1px solid var(--line);
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(130deg, rgba(0,0,0,0.75), rgba(230,57,70,0.18));
}
.hero > * { position: relative; z-index: 2; }
.eyebrow { color: var(--accent); text-transform: uppercase; letter-spacing: 0.15em; font-weight: 700; }
.hero h1, h1, h2, h3 {
  font-family: 'Oswald', 'Bebas Neue', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin: 0;
}
.hero h1 { font-size: clamp(2rem, 5.8vw, 4.5rem); max-width: 16ch; margin-inline: auto; }
.hero p { color: #ddd; max-width: 62ch; margin: 1rem auto 1.8rem; }
.hero-actions { display: flex; gap: 0.8rem; justify-content: center; flex-wrap: wrap; }

section { padding: 4.2rem 0; }
section h2 { font-size: clamp(1.7rem, 3.3vw, 2.8rem); margin-bottom: 0.9rem; }
.section-copy { color: var(--muted); max-width: 70ch; }

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}
.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.2rem;
}

.carousel {
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--line);
  background: #000;
}
.carousel-track {
  display: flex;
  transition: transform 0.45s ease;
  touch-action: pan-y;
}
.slide {
  min-width: 100%;
  height: 420px;
  position: relative;
}
.slide img { width: 100%; height: 100%; object-fit: cover; filter: brightness(0.72) saturate(1.1); }
.slide-caption {
  position: absolute;
  left: 1.2rem;
  bottom: 1rem;
  background: rgba(0,0,0,0.58);
  padding: 0.7rem 0.9rem;
  border-radius: 8px;
  font-weight: 600;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.5);
  background: rgba(0,0,0,0.55);
  color: #fff;
  cursor: pointer;
}
.carousel-btn.prev { left: 12px; }
.carousel-btn.next { right: 12px; }

.cta-band {
  background: linear-gradient(120deg, #21090b, #111);
  border: 1px solid #4a1e22;
  border-radius: 14px;
  padding: 2rem;
  text-align: center;
}
.cta-band h2 { font-size: clamp(2rem, 4.2vw, 3.5rem); margin-bottom: 0.6rem; }

.toggle-wrap { margin-top: 1rem; }
.toggle-group {
  display: inline-flex;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 0.2rem;
  background: #171717;
}
.toggle-btn {
  border: none;
  background: transparent;
  color: var(--muted);
  padding: 0.7rem 1.1rem;
  border-radius: 999px;
  cursor: pointer;
  text-transform: uppercase;
  font-weight: 700;
}
.toggle-btn.active { background: var(--accent); color: #fff; }
.toggle-panel { margin-top: 1rem; }

.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 12px; }
table { width: 100%; border-collapse: collapse; min-width: 620px; }
th, td { padding: 0.85rem 0.9rem; text-align: left; border-bottom: 1px solid var(--line); }
th { background: #161616; text-transform: uppercase; font-size: 0.83rem; letter-spacing: 0.04em; }
tr:hover td { background: #181818; }

.filter-bar { display: flex; gap: 0.8rem; align-items: center; flex-wrap: wrap; margin-bottom: 1rem; }
select, input[type='email'] {
  background: #141414;
  color: #fff;
  border: 1px solid #333;
  border-radius: 10px;
  padding: 0.75rem 0.85rem;
  min-height: 44px;
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 1rem;
}
.instructor-card img {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  border-radius: 10px;
  margin-bottom: 0.7rem;
}
.tag { color: #fff; background: #2a2a2a; padding: 0.2rem 0.55rem; border-radius: 999px; font-size: 0.78rem; }

.accordion-item {
  border: 1px solid var(--line);
  border-radius: 10px;
  margin-bottom: 0.7rem;
  overflow: hidden;
}
.accordion-btn {
  width: 100%;
  text-align: left;
  border: none;
  background: #161616;
  color: #fff;
  padding: 1rem;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  min-height: 44px;
}
.accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  background: #1d1d1d;
}
.accordion-panel .inner { padding: 0 1rem 1rem; color: #d6d6d6; }
.accordion-item.open .accordion-panel { max-height: 180px; }

.newsletter {
  background: #161616;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 1.2rem;
}
.newsletter form { display: flex; gap: 0.7rem; flex-wrap: wrap; }
.feedback { margin-top: 0.6rem; font-size: 0.92rem; }
.feedback.error { color: var(--danger); }
.feedback.success { color: var(--success); }

footer {
